import re
from pathlib import Path
root = Path('tests')
CONSTS = ('_REPO_ROOT','REPO_ROOT','PROJECT_ROOT','_TESTS_ROOT','TESTS_ROOT','_SCRIPTS_ROOT','SCRIPTS_ROOT','SCRIPTS_DIR','_API_ROOT')
WALK = re.compile(r'\.(rglob|glob)\(|os\.walk\(|iglob\(')
RECV = re.compile(r'([\w\.\[\]"\' /\(\)\-]{1,80})\.(?:rglob|glob)\(')
SCANNER = re.compile(r'\b(?:find_stale_pinned_assertions|scan_scripts|timeout_less_calls|timeout_less_calls_from_source|_inplace_manifest_writers|production_sites|_iter_surface_python_files|scan_orchestrator_suites|lint_fleet_roster|lint_agent_skills|lint_model_catalog|lint_prompts)\s*\(')
for mod in sorted(root.rglob('test_*.py')):
    txt = mod.read_text(encoding='utf-8', errors='replace')
    hits=[]
    for i,l in enumerate(txt.splitlines(),1):
        if 'tmp_path' in l or 'tmpdir' in l or 'tmp' in l.lower() and ('/' in l and 'tmp' in l):
            continue
        if SCANNER.search(l):
            hits.append((i,'scanner',l.strip()[:80]))
        elif WALK.search(l):
            m=RECV.search(l); r=m.group(1) if m else ''
            if any(c in r for c in CONSTS):
                hits.append((i,'walk',l.strip()[:80]))
    if hits:
        print('###',mod.as_posix())
        for h in hits[:3]:
            print('   ',h)
